var i=`0339-macarons`;var a=`world-0339`;var r=`FR`;var n=`western-europe`;var o=8;var s=87;var l={en:`Macarons`,ua:`Макарони`};var g={en:`A traditional France dish made with almond flour, pasteurized egg whites. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: мигдалеве борошно, пастеризовані яєчні білки. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Sift almond flour with powdered sugar. Whip pasteurized egg whites with granulated sugar into a stable meringue and fold until it flows in thick ribbons.`,ua:`Просійте мигдальне борошно з цукровою пудрою. Збийте пастеризовані білки з цукром у стійку меренгу та змішайте до консистенції густої стрічки.`,t:[`whipping-egg-foam`,`folding-batter`],m:9,i:[[`almond-flour`,200,`g`],[`powdered-sugar`,200,`g`],[`pasteurized-egg-whites`,160,`g`],[`white-granulated-sugar`,175,`g`]]},{en:`Pipe uniform circles onto parchment and tap the tray to remove bubbles.`,ua:`Відсадіть рівні кружальця на пергамент і легенько постукайте деком, щоб видалити бульбашки.`,t:[`piping-batter`],m:16,i:[]},{en:`Rest the piped shells for 30–40 minutes until a dry skin forms and a fingertip no longer sticks.`,ua:`Витримайте заготовки 30–40 хвилин до сухої плівки, щоб поверхня не прилипала до пальця.`,t:[`air-drying`],m:40,i:[]},{en:`Bake the shells at 145–155°C for about 15 minutes; let cool fully before removing from the tray.`,ua:`Випікайте оболонки при 145–155°C близько 15 хвилин; повністю охолодіть перед зняттям із дека.`,t:[`baking`],m:15,i:[]},{en:`Cream butter with vanilla and powdered sugar, fill the cooled shells and sandwich pairs together. Refrigerate overnight for the proper texture.`,ua:`Збийте масло з ваніллю та пудрою, наповніть охолоджені половинки кремом і з’єднайте попарно. Витримайте в холодильнику на ніч для потрібної текстури.`,t:[`chopping`,`mixing`],m:7,i:[[`unsalted-butter`,150,`g`],[`vanilla-extract`,5,`ml`],[`powdered-sugar`,65,`g`]]}];var d={slug:i,id:a,country:`FR`,region:n,servings:8,minutes:87,title:l,text:g,steps:u};export{r as country,d as default,a as id,s as minutes,n as region,o as servings,i as slug,u as steps,g as text,l as title};